import * as THREE from 'three';
import { RGBELoader } from 'three/examples/jsm/loaders/RGBELoader'; //loader for RGBE format (Radiance HDR)

export default class WorldScene {
    constructor(container, visitedFromMobileDevice) {
        this.container = container;
        this.init();
        this.addLights();
        this.addFog();

        this.envMap = null;
        //this.addSkybox(visitedFromMobileDevice);

    }

    init() {
        this.scene = new THREE.Scene();
        this.camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 1.0, 2500);

        this.renderer = new THREE.WebGLRenderer({
            powerPreference: "high-performance",
            antialias: false,
            stencil: false,
            depth: false,
            //alpha: true
        });
        let pixelRatio = window.devicePixelRatio;
        this.renderer.setPixelRatio(pixelRatio > 2 ? 1.5 : pixelRatio);
        this.renderer.outputEncoding = THREE.SRGBColorSpace;

        this.renderer.shadowMap.enabled = true;
        this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        this.renderer.shadowMap.autoUpdate = true;

        //this.renderer.outputEncoding = THREE.sRGBEncoding;
        //this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
        //this.renderer.toneMapping = THREE.NoToneMapping;
        this.renderer.toneMappingExposure = 0.2;
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        this.container.appendChild(this.renderer.domElement);


        // Resize Observer
        this.resizeObserver = new ResizeObserver(entries => {
            for (let entry of entries) {
                const { width, height } = entry.contentRect;
                this.renderer.setSize(width, height);
                this.camera.aspect = width / height;
                this.camera.updateProjectionMatrix();

            }
        });

        this.resizeObserver.observe(this.container);

    }

    addLights() {
        //const dayLight = new THREE.HemisphereLight(0xfff2c7, 0x080820, 2.35);
        const dayLight = new THREE.DirectionalLight(0xfff2c7, 1.2)
        //fff2c7
        //F2E6BD
        dayLight.position.set(0, 50, 50)
        //f2e1aa
        //F2E6BD
        //worldScene.scene.add(dayLight);

        //const helperDir = new THREE.DirectionalLightHelper(dayLight, 5);
        //worldScene.scene.add(helperDir);

        const widthLight = 200;
        const height = 90;
        const intensity = 8; //9
        //const rectLight = new THREE.RectAreaLight(0xf1f3e1, intensity, widthLight, height);
        //0xa9dbfd
        const rectLight = new THREE.RectAreaLight(0xF2E6BD, intensity, widthLight, height);
        const rectLight2 = new THREE.RectAreaLight(0xF2E6BD, 7, 320, 80); //8
        //82ccff
        rectLight2.position.set(0, 0, 0);
        rectLight2.lookAt(0, 0, 100);

        rectLight.position.set(0, 40, 145);
        rectLight.lookAt(0, 0, 125);
        this.scene.add(rectLight2)
        this.scene.add(rectLight)
    }

    addFog() {
        this.scene.fog = new THREE.FogExp2(0x56515f, 0.0026); // 0.0017 is the density of the fog
        //45414d
        //44424d


        //4b4856
        //56545c
        //64616b
        //9692a1
        //9998ab
        //f2dfa0

    }

    addSkybox(visitedFromMobileDevice) {
        // Create a PMREMGenerator
        const pmremGenerator = new THREE.PMREMGenerator(this.renderer);
        pmremGenerator.compileEquirectangularShader();

        //let skyboxToLoad = visitedFromMobileDevice ? 'belfast_sunset_puresky_1k' : 'belfast_sunset_puresky_1k';
        let skyboxToLoad = visitedFromMobileDevice ? 'belfast_sunset_puresky_1k' : 'belfast_sunset_puresky_2k';
        //let envMap = null;

        // Load the HDR texture
        const rgbeLoader = new RGBELoader();

        rgbeLoader.load(`./assets/${skyboxToLoad}.hdr`, function (texture) {
            texture.mapping = THREE.EquirectangularReflectionMapping; // Use equirectangular mapping
            // Convert the HDR texture to a cubemap


            if (this.envMap) {
                this.envMap = pmremGenerator.fromEquirectangular(texture).texture;
                this.scene.background = this.envMap;
            }

            // Dispose of the PMREMGenerator to free up resources
            pmremGenerator.dispose();

            // Dispose of the original HDR texture
            texture.dispose();
        });

    }
    getEnvMap() {
        return this.envMap;
    }

    getRenderer() {
        return this.renderer;
    }

    getCamera() {
        return this.camera;
    }
}
